---
import type { HTMLAttributes } from "astro/types"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

type Props = HTMLAttributes<"aside"> &
  VariantProps<typeof variants> & {
    storageKey?: string
  }

const variants = cva("py-2.5 relative flex items-center", {
  variants: {
    variant: {
      default: "bg-foreground text-background w-full",
      floating:
        "my-2 rounded-4xl bg-background shadow-md ring-1 ring-foreground/5 dark:ring-foreground/10 mx-auto w-[calc(100%-2*var(--gutter,--spacing(4)))] max-w-[calc(var(--container,var(--container-7xl))-2*var(--gutter,--spacing(4)))] overflow-hidden",
    },
  },
  defaultVariants: {
    variant: "default",
  },
})

const {
  class: className,
  variant = "default",
  storageKey,
  ...props
} = Astro.props
---

<aside
  class={cn(variants({ variant }), className)}
  data-slot="banner"
  data-banner-storage-key={storageKey}
  data-variant={variant}
  {...props}
>
  <slot />
</aside>

<script>
  const getStorageToken = (key: string) => `banner:${key}`

  const syncBanners = () => {
    document.querySelectorAll("[data-slot='banner']").forEach((banner) => {
      if (!(banner instanceof HTMLElement)) return
      const storageKey = banner.dataset.bannerStorageKey
      if (
        storageKey &&
        sessionStorage.getItem(getStorageToken(storageKey)) === "hidden"
      ) {
        banner.hidden = true
      }
    })
  }

  syncBanners()
  document.addEventListener("astro:page-load", syncBanners)

  document.addEventListener("click", (event) => {
    if (!(event.target instanceof Element)) return
    const closeButton = event.target.closest("[data-slot='banner-close']")
    const banner = closeButton?.closest("[data-slot='banner']")
    if (!(banner instanceof HTMLElement)) return
    banner.hidden = true
    const storageKey = banner.dataset.bannerStorageKey
    if (storageKey)
      sessionStorage.setItem(getStorageToken(storageKey), "hidden")
  })
</script>

---
import type { HTMLAttributes } from "astro/types"
import XIcon from "@lucide/astro/icons/x"

import { cn } from "@/lib/utils"

type Props = HTMLAttributes<"div"> & {
  showClose?: boolean
  closeLabel?: string
}

const {
  class: className,
  showClose = true,
  closeLabel = "Close",
  "data-slot": dataSlot = "banner-container",
  ...props
} = Astro.props
---

<div
  class={cn(
    "relative mx-auto flex w-full max-w-[var(--container,var(--container-7xl))] gap-4 px-[var(--gutter,--spacing(4))]",
    showClose && "pr-10",
    className
  )}
  data-slot={dataSlot}
  {...props}
>
  <slot />
  {showClose && (
    <button
      type="button"
      class="rounded-full text-current/65 hover:text-current focus-visible:text-current focus-visible:ring-2 focus-visible:ring-ring/50 absolute top-1/2 right-4 z-20 inline-flex shrink-0 -translate-y-1/2 items-center justify-center transition-colors outline-none disabled:pointer-events-none disabled:opacity-50 in-[[data-variant=floating]]:right-5"
      aria-label={closeLabel}
      data-slot="banner-close"
    >
      <XIcon class="size-4" />
      <span class="sr-only">{closeLabel}</span>
    </button>
  )}
</div>
